import{_ as i,o as a,c as n,ai as l}from"./chunks/framework.BxxKhjs3.js";const p="/pub-blog/assets/image-20251223090201185.St_-8LBu.png",e="/pub-blog/assets/image-20251223085504793.BSjo2ERx.png",t="/pub-blog/assets/image-20251223090845310.CWvUmURx.png",h="/pub-blog/assets/image-20251223090838505.BihRdY4T.png",b=JSON.parse('{"title":"HarmonyOS6 接入快手 SDK 指南","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/HarmonyOS6 接入快手 SDK 指南/HarmonyOS6 接入快手 SDK 指南.md","filePath":"鸿蒙开发技巧/HarmonyOS6 接入快手 SDK 指南/HarmonyOS6 接入快手 SDK 指南.md","lastUpdated":1766452298000,"__rawMarkdown":"# HarmonyOS6 接入快手 SDK 指南\\n\\n## 介绍\\n\\n目前快手开放了 授权、发布单图、发布单视频的鸿蒙能力，开发者如果有需要接入，可以按照以下流程操作。\\n\\n\\n\\n\\n\\n## 效果一览\\n\\n![](assets/image-20251223090201185.png)\\n\\n## 环境准备\\n\\n开发者需要在快手开放平台完成**注册**，新建一个**应用**，并获取**应用标识 appId** ，详细参考申请注册流程，官网地址：https://open.kuaishou.com/platform\\n\\n\\n\\n## 环境要求\\n\\n- 快手版本 >= 13.0.10\\n- 鸿蒙SDK版本 >= 12\\n\\n## 接入步骤\\n\\n1. 在模块中引入 SDK依赖，如 Entry模块\\n\\n```json\\n  \\"dependencies\\": {\\n    \\"@kwai_open_platform/opensdk\\": \\"^1.0.1\\"\\n  }\\n```\\n\\n2. 在 entry 模块下的 module.json5 文件中添加querySchemes配置。\\n\\n> 在鸿蒙应用的`module.json5`文件中配置`querySchemes`的作用是**声明应用支持的URL协议（URL Scheme）**，允许其他应用或网页通过特定格式的URL调起当前应用。具体解析如下：\\n>\\n> 1. **核心功能实现**\\n>    示例中配置的`\\"kwai\\"`和`\\"ksnebula\\"`表示该应用可以响应以下两种格式的URL请求：\\n>    - `kwai://...`\\n>    - `ksnebula://...`\\n>      当其他应用或系统触发这类链接时，鸿蒙系统会尝试启动当前应用并传递参数。\\n> 2. **典型应用场景**\\n>    - 跨应用跳转：其他应用通过`startAbility`发送包含对应Scheme的Want对象调起本应用\\n>    - 网页跳转：在浏览器中点击`<a href=\\"kwai://detail?id=123\\">`类链接触发应用打开\\n>    - 广告引流：通过短信、二维码等方式引导用户通过特定Scheme打开应用指定页面\\n\\n```json\\n{\\n  \\"module\\": {\\n    \\"querySchemes\\": [\\n      \\"kwai\\",\\n      \\"ksnebula\\"\\n    ]\\n  }\\n}\\n\\n```\\n\\n3. 同时还需求申请网络权限\\n\\n```json\\n    \\"requestPermissions\\": [\\n      {\\n        \\"name\\" : \\"ohos.permission.INTERNET\\"\\n      }\\n    ]\\n```\\n\\n\\n\\n4. 在接受回调的 UIAbility 的 onCreate 和 onNewWant 方法中，调用 kwaiOpenSdk.handleCallback 方法处理回调数据。\\n\\n> **onCreate** 表示应用首次启动\\n>\\n> **onNewWant** 表示应用已经启动的，然后被重新拉起\\n\\n```typescript\\nimport { kwaiOpenSdk } from \'@kwai_open_platform/opensdk/src/main/ets/KwaiOpensdk\';\\n\\nexport default class EntryAbility extends UIAbility {\\n  onCreate(want: Want, launchParam: AbilityConstant.LaunchParam): void {\\n    kwaiOpenSdk.handleCallback(want)\\n  }\\n\\n  onNewWant(want: Want, launchParam: AbilityConstant.LaunchParam): void {\\n    kwaiOpenSdk.handleCallback(want)\\n  }\\n}\\n\\n```\\n\\n5. 初始化SDK，如在 Index.ets的aboutToAppear中初始化\\n\\n```typescript\\n  aboutToAppear(): void {\\n    // 初始化快手SDK\\n    kwaiOpenSdk.init(this.context);\\n  }\\n```\\n\\n\\n\\n## 相关功能\\n\\n目前SDK提供有 授权 和 发布单图和发单视频能力，开发者可以根据需求引入使用\\n\\n### 初始化代码数据\\n\\n> 定义快手应用ID **APPID**\\n>\\n> 定义鸿蒙应用ID  harmonyAppID\\n>\\n> 定义媒体选择通用方法 **selectMedia**\\n\\n```typescript\\n// 导入快手开放平台SDK\\nimport { kwaiOpenSdk } from \'@kwai_open_platform/opensdk/src/main/ets/KwaiOpensdk\';\\n// 导入AbilityKit相关组件\\nimport { common } from \'@kit.AbilityKit\';\\n// 导入授权请求模型\\nimport { AuthRequest } from \'@kwai_open_platform/opensdk/src/main/ets/model/request/AuthRequest\';\\n// 导入授权响应模型\\nimport { AuthResponse } from \'@kwai_open_platform/opensdk/src/main/ets/model/response/AuthResponse\';\\n// 导入日志工具\\nimport { Logger } from \'@kwai_open_platform/opensdk/src/main/ets/utils/Logger\';\\n// 导入分享请求模型创建函数\\nimport {\\n  createSingleImagePublish,\\n  createSingleVideoPublish\\n} from \'@kwai_open_platform/opensdk/src/main/ets/model/request/ShareRequest\';\\n// 导入ArkTS集合框架\\nimport { ArrayList } from \'@kit.ArkTS\';\\n// 导入媒体库访问助手\\nimport { photoAccessHelper } from \'@kit.MediaLibraryKit\';\\n// 导入文件操作相关工具\\nimport { fileIo, fileUri } from \'@kit.CoreFileKit\';\\n\\n// 定义快手应用ID\\nconst APPID = \\"ks669910448092164647\\"\\n\\n// 定义鸿蒙应用ID\\nconst harmonyAppID: string = \\"6917560710208292268\\";\\n\\n@Entry\\n@Component\\nstruct Index {\\n  // 获取UIAbility上下文\\n  context = this.getUIContext().getHostContext() as common.UIAbilityContext;\\n  // 回调结果状态\\n  @State callbackResult: boolean = false;\\n  // 授权码\\n  @State authCode: string = \\"\\";\\n  // 错误信息\\n  @State errMsg: string = \\"\\";\\n  // 错误码\\n  @State errCode: number = -1;\\n\\n  aboutToAppear(): void {\\n    // 初始化快手SDK\\n    kwaiOpenSdk.init(this.context);\\n  }\\n\\n\\n  // 媒体选择通用方法\\n  private selectMedia<T>(\\n    callback: (t: T) => void,\\n    type: photoAccessHelper.PhotoViewMIMETypes.IMAGE_TYPE | photoAccessHelper.PhotoViewMIMETypes.VIDEO_TYPE,\\n    num: number = 1\\n  ) {\\n    // 创建照片选择选项\\n    let photoOptions = new photoAccessHelper.PhotoSelectOptions();\\n    // 设置MIME类型（图片或视频）\\n    photoOptions.MIMEType = type;\\n    // 设置最大选择数量\\n    photoOptions.maxSelectNumber = num;\\n\\n    // 创建照片选择器\\n    let picker = new photoAccessHelper.PhotoViewPicker();\\n    // 调用选择方法\\n    picker.select(photoOptions).then((photoSelectResult: photoAccessHelper.PhotoSelectResult) => {\\n      // 获取选中的URI列表\\n      let uris: Array<string> = photoSelectResult.photoUris;\\n      if (uris.length > 0) {\\n        // 获取第一个URI\\n        let str = uris[0];\\n        // 提取文件名\\n        let fileName = str.substring(str.lastIndexOf(\'/\'));\\n        // 构建目标文件路径\\n        let desFilePath = this.context.getApplicationContext().tempDir + fileName;\\n        // 打开源文件（只读）\\n        let srcFile = fileIo.openSync(str, fileIo.OpenMode.READ_ONLY);\\n        // 打开目标文件（写，如不存在则创建）\\n        let desFile = fileIo.openSync(desFilePath, fileIo.OpenMode.WRITE_ONLY | fileIo.OpenMode.CREATE);\\n        // 复制文件内容\\n        fileIo.copyFileSync(srcFile.fd, desFile.fd)\\n        // 回调处理，传递文件URI\\n        callback?.(fileUri.getUriFromPath(desFilePath) as T);\\n      } else {\\n        // 未选择资源时显示提示\\n        this.getUIContext().getPromptAction().showToast({\\n          message: \'没有选择资源\'\\n        })\\n      }\\n    }).catch((error: BusinessError) => {\\n      // 选择出错时显示提示\\n      this.getUIContext().getPromptAction().showToast({\\n        message: \'选择资源error\'\\n      })\\n    })\\n  }\\n}\\n```\\n\\n\\n\\n### 接入快手授权能力\\n\\n![](assets/image-20251223085504793.png)\\n\\n参数说明:\\n\\n| 参数               | 说明                                                         | 是否必填 |\\n| ------------------ | ------------------------------------------------------------ | -------- |\\n| requiredScopes     | 申请获取用户的那些授权信息，如果需要多个scope，用 “,” 分割。比如：user_info,user_phone | 是       |\\n| optional0Scopes    | 可选scope，授权页可以取消勾选，默非认勾选态                  | 否       |\\n| optional1Scopes    | 可选scope，授权页可以取消勾选，默认勾选态                    | 否       |\\n| callbackLocalEntry | 回调的UIAbility名称，需要在module.json中声明                 | 是       |\\n| abilityContext     | 如果没有安装快手，会跳转到应用市场安装。不传则不会跳转到应用市场 | 否       |\\n\\n```typescript\\n  // 授权功能实现\\n  fn1 = () => {\\n    {\\n      // 创建授权请求对象\\n      let request = new AuthRequest(APPID);\\n      // 设置必需的权限范围\\n      request.requiredScopes = \\"user_phone,user_info\\";\\n      // 设置可选权限范围0\\n      request.optional0Scopes = \\"user_base,share_media,following,share_message\\"\\n      // 设置可选权限范围1\\n      request.optional1Scopes = \\"user_growth_distribution,message,live,relation\\"\\n      // 设置回调入口\\n      request.callbackLocalEntry = \\"EntryAbility\\";\\n      // 设置Ability上下文\\n      request.abilityContext = this.context;\\n      // 重要提示，这行代码不要复制\\n      request.harmonyAppId = harmonyAppID\\n      // 调用SDK授权接口\\n      kwaiOpenSdk.createApi().authorize(this.context, request, {\\n        // 授权成功回调\\n        onSuccess: (res) => {\\n          Logger.i(\\"authCallback\\", \\"success.......\\");\\n          // 保存授权码\\n          this.authCode = (res as AuthResponse).code;\\n          // 设置回调结果为成功\\n          this.callbackResult = true;\\n        },\\n        // 授权失败回调\\n        onError: (errorCode, msg) => {\\n          Logger.i(\\"authCallback\\", `failed, code: ${errorCode}, msg: ${msg}`);\\n          // 保存错误信息\\n          this.errMsg = msg\\n          this.errCode = errorCode\\n          // 设置回调结果为失败\\n          this.callbackResult = false;\\n        }\\n      })\\n    }\\n  }\\n```\\n\\n### 授权-错误码\\n\\n| 错误码    | 描述                                                         |\\n| --------- | ------------------------------------------------------------ |\\n| 999       | 成功                                                         |\\n| 1000      | appId is empty                                               |\\n| 1001      | request is error                                             |\\n| 1002      | request is empty                                             |\\n| 1003      | request bundle id is empty                                   |\\n| 1004      | request harmony app id is empty                              |\\n| 1005      | not install kuaishou app                                     |\\n| 2000      | auth request requiredScopes is empty                         |\\n| 2002      | 无效的授权内容                                               |\\n| 2101      | 提交授权信息失败，缺少授权参数                               |\\n| 100200100 | 请求缺少参数或参数类型错误                                   |\\n| 100200101 | 无效的client，无效的 app 或 developer，可能是验证参数不正确（回调地址等信息） |\\n| 100200102 | 请求被拒绝，可能是无效的 token 等                            |\\n| 100200103 | 请求的 responseType 错误                                     |\\n| 100200104 | 请求的 grantType 不支持                                      |\\n| 100200105 | 请求的 code 错误                                             |\\n| 100200106 | 请求的 scope 错误                                            |\\n| 100200107 | 无效的 openid                                                |\\n| 100200108 | access_token过期                                             |\\n| 100200109 | 用户取消该 app 授权                                          |\\n| 100200110 | 用户授权过期                                                 |\\n| 100200111 | 用户未授权过                                                 |\\n| 100200112 | bundleToken不合法                                            |\\n| 100200113 | refresh_token过期                                            |\\n| 100200500 | 服务内部错误                                                 |\\n\\n### 接入发布单图能力\\n\\n![](assets/image-20251223090845310.png)\\n\\n1. **分享请求构建**：\\n\\n   1. 使用`createSingleImagePublish(APPID)`创建单图分享请求对象\\n\\n   2. 初始化`ArrayList`存储媒体URI列表，并添加选中图片的URI\\n\\n   3. 设置`callbackLocalEntry`指定回调入口为**EntryAbility**\\n\\n2. **关键参数配置**：\\n\\n   1. 显式设置`harmonyAppId`参数（注释提示该行代码具有重要性）\\n\\n   2. 通过上下文`this.context`保持与当前页面的关联\\n\\n3. **SDK调用与结果处理**：\\n\\n   调用`kwaiOpenSdk.createApi().share()`方法执行实际分享操作\\n\\n```typescript\\n  fn2 = () => {\\n    // 调用媒体选择方法，指定图片类型\\n    this.selectMedia<string>((url: string) => {\\n      // 创建单图分享请求对象\\n      let shareRequest = createSingleImagePublish(APPID);\\n      // 创建媒体URI列表\\n      let list: ArrayList<string> = new ArrayList();\\n      // 添加选中的图片URI\\n      list.add(url);\\n      // 设置媒体URI列表\\n      shareRequest.mediaUri = list;\\n      // 设置回调入口\\n      shareRequest.callbackLocalEntry = \\"EntryAbility\\";\\n      // 重要提示，这行代码不要复制\\n      shareRequest.harmonyAppId = harmonyAppID\\n\\n      // 调用SDK分享接口\\n      kwaiOpenSdk.createApi().share(this.context, shareRequest, {\\n        // 分享成功回调\\n        onSuccess: (res) => {\\n          // 设置回调结果为成功\\n          this.callbackResult = true;\\n          Logger.i(\\"shareCallback\\", \\"success.......\\");\\n        },\\n        // 分享失败回调\\n        onError: (errorCode, msg) => {\\n          // 设置回调结果为失败\\n          this.callbackResult = false;\\n          // 保存错误信息\\n          this.errMsg = msg\\n          this.errCode = errorCode\\n          Logger.i(\\"shareCallback\\", `failed, code: ${errorCode}, msg: ${msg}`);\\n        }\\n      })\\n    }, photoAccessHelper.PhotoViewMIMETypes.IMAGE_TYPE);\\n  }\\n```\\n\\n\\n\\n### 接入发布单视频能力\\n\\n![](assets/image-20251223090838505.png)\\n\\n1. **视频分享请求构建**\\n   1. 对象创建：`createSingleVideoPublish(APPID)`生成视频分享请求对象（区别于图片接口）\\n   2. 媒体列表管理：\\n\\n   - 初始化`ArrayList`容器\\n   - 将视频URI添加到容器\\n   - 设置请求的`mediaUri`属性为容器对象\\n\\n2. **关键参数配置**\\n\\n   1. `callbackLocalEntry`指定回调入口为\\"EntryAbility\\"（需与实际Ability名称一致）\\n\\n   2. `harmonyAppId`显式赋值（通过独立变量`harmonyAppID`注入，需确保配置有效性）\\n\\n3. **SDK调用与响应处理**\\n\\n   通过`kwaiOpenSdk.createApi().share()`发起分享请求，传入上下文对象和配置参\\n\\n```typescript\\n  // 发布单视频功能实现\\n  fn3 = () => {\\n    // 调用媒体选择方法，指定视频类型\\n    this.selectMedia<string>((url: string) => {\\n      // 创建单视频分享请求对象\\n      let shareRequest = createSingleVideoPublish(APPID);\\n      // 创建媒体URI列表\\n      let list: ArrayList<string> = new ArrayList();\\n      // 添加选中的视频URI\\n      list.add(url);\\n      // 设置媒体URI列表\\n      shareRequest.mediaUri = list;\\n      // 设置回调入口\\n      shareRequest.callbackLocalEntry = \\"EntryAbility\\";\\n      // 重要提示，这行代码不要复制\\n      shareRequest.harmonyAppId = harmonyAppID\\n      // 调用SDK分享接口\\n      kwaiOpenSdk.createApi().share(this.context, shareRequest, {\\n        // 分享成功回调\\n        onSuccess: (res) => {\\n          // 设置回调结果为成功\\n          this.callbackResult = true;\\n          Logger.i(\\"shareCallback\\", \\"success.......\\");\\n        },\\n        // 分享失败回调\\n        onError: (errorCode, msg) => {\\n          // 设置回调结果为失败\\n          this.callbackResult = false;\\n          // 保存错误信息\\n          this.errMsg = msg\\n          this.errCode = errorCode\\n          Logger.i(\\"shareCallback\\", `failed, code: ${errorCode}, msg: ${msg}`);\\n        }\\n      })\\n    }, photoAccessHelper.PhotoViewMIMETypes.VIDEO_TYPE);\\n  }\\n```\\n\\n### 发布单图-发布单视频的错误码\\n\\n| 错误码 | 描述                                                         |\\n| ------ | ------------------------------------------------------------ |\\n| 999    | 成功                                                         |\\n| 1000   | appId is empty                                               |\\n| 1001   | request is error                                             |\\n| 1002   | request is empty                                             |\\n| 1003   | request bundle id is empty                                   |\\n| 1004   | request harmony app id is empty                              |\\n| 1005   | not install kuaishou app                                     |\\n| 3000   | 用户取消                                                     |\\n| 3001   | 框架出错，请反馈客服                                         |\\n| 3002   | 参数错误，包含shareType、appId、harmonyId、mediaUri等相关参数 |\\n| 3003   | 打开发布页失败                                               |\\n| 3004   | 网络错误                                                     |\\n| 3005   | 发布请求过于频繁（3s内重复调用）                             |\\n| 3006   | 视频size超过最大大小                                         |\\n| 3007   | 图片size超过最大大小                                         |\\n| 3008   | 拒绝当次分享动作；如果是发布视频:请检查视频长度              |\\n| 3009   | 鉴权失败                                                     |\\n\\n\\n\\n## 完整 Index.ets 代码\\n\\n```typescript\\n// 导入快手开放平台SDK\\nimport { kwaiOpenSdk } from \'@kwai_open_platform/opensdk/src/main/ets/KwaiOpensdk\';\\n// 导入AbilityKit相关组件\\nimport { common } from \'@kit.AbilityKit\';\\n// 导入授权请求模型\\nimport { AuthRequest } from \'@kwai_open_platform/opensdk/src/main/ets/model/request/AuthRequest\';\\n// 导入授权响应模型\\nimport { AuthResponse } from \'@kwai_open_platform/opensdk/src/main/ets/model/response/AuthResponse\';\\n// 导入日志工具\\nimport { Logger } from \'@kwai_open_platform/opensdk/src/main/ets/utils/Logger\';\\n// 导入分享请求模型创建函数\\nimport {\\n  createSingleImagePublish,\\n  createSingleVideoPublish\\n} from \'@kwai_open_platform/opensdk/src/main/ets/model/request/ShareRequest\';\\n// 导入ArkTS集合框架\\nimport { ArrayList } from \'@kit.ArkTS\';\\n// 导入媒体库访问助手\\nimport { photoAccessHelper } from \'@kit.MediaLibraryKit\';\\n// 导入文件操作相关工具\\nimport { fileIo, fileUri } from \'@kit.CoreFileKit\';\\n\\n// 定义快手应用ID\\nconst APPID = \\"ks669910448092164647\\"\\n\\n// 定义鸿蒙应用ID\\nconst harmonyAppID: string = \\"6917560710208292268\\";\\n\\n@Entry\\n@Component\\nstruct Index {\\n  // 获取UIAbility上下文\\n  context = this.getUIContext().getHostContext() as common.UIAbilityContext;\\n  // 回调结果状态\\n  @State callbackResult: boolean = false;\\n  // 授权码\\n  @State authCode: string = \\"\\";\\n  // 错误信息\\n  @State errMsg: string = \\"\\";\\n  // 错误码\\n  @State errCode: number = -1;\\n\\n  aboutToAppear(): void {\\n    // 初始化快手SDK\\n    kwaiOpenSdk.init(this.context);\\n  }\\n\\n  // 授权功能实现\\n  fn1 = () => {\\n    {\\n      // 创建授权请求对象\\n      let request = new AuthRequest(APPID);\\n      // 设置必需的权限范围\\n      request.requiredScopes = \\"user_phone,user_info\\";\\n      // 设置可选权限范围0\\n      request.optional0Scopes = \\"user_base,share_media,following,share_message\\"\\n      // 设置可选权限范围1\\n      request.optional1Scopes = \\"user_growth_distribution,message,live,relation\\"\\n      // 设置回调入口\\n      request.callbackLocalEntry = \\"EntryAbility\\";\\n      // 设置Ability上下文\\n      request.abilityContext = this.context;\\n      // 重要提示，这行代码不要复制\\n      request.harmonyAppId = harmonyAppID\\n      // 调用SDK授权接口\\n      kwaiOpenSdk.createApi().authorize(this.context, request, {\\n        // 授权成功回调\\n        onSuccess: (res) => {\\n          Logger.i(\\"authCallback\\", \\"success.......\\");\\n          // 保存授权码\\n          this.authCode = (res as AuthResponse).code;\\n          // 设置回调结果为成功\\n          this.callbackResult = true;\\n        },\\n        // 授权失败回调\\n        onError: (errorCode, msg) => {\\n          Logger.i(\\"authCallback\\", `failed, code: ${errorCode}, msg: ${msg}`);\\n          // 保存错误信息\\n          this.errMsg = msg\\n          this.errCode = errorCode\\n          // 设置回调结果为失败\\n          this.callbackResult = false;\\n        }\\n      })\\n    }\\n  }\\n  // 发布单图功能实现\\n  fn2 = () => {\\n    // 调用媒体选择方法，指定图片类型\\n    this.selectMedia<string>((url: string) => {\\n      // 创建单图分享请求对象\\n      let shareRequest = createSingleImagePublish(APPID);\\n      // 创建媒体URI列表\\n      let list: ArrayList<string> = new ArrayList();\\n      // 添加选中的图片URI\\n      list.add(url);\\n      // 设置媒体URI列表\\n      shareRequest.mediaUri = list;\\n      // 设置回调入口\\n      shareRequest.callbackLocalEntry = \\"EntryAbility\\";\\n      // 重要提示，这行代码不要复制\\n      shareRequest.harmonyAppId = harmonyAppID\\n\\n      // 调用SDK分享接口\\n      kwaiOpenSdk.createApi().share(this.context, shareRequest, {\\n        // 分享成功回调\\n        onSuccess: (res) => {\\n          // 设置回调结果为成功\\n          this.callbackResult = true;\\n          Logger.i(\\"shareCallback\\", \\"success.......\\");\\n        },\\n        // 分享失败回调\\n        onError: (errorCode, msg) => {\\n          // 设置回调结果为失败\\n          this.callbackResult = false;\\n          // 保存错误信息\\n          this.errMsg = msg\\n          this.errCode = errorCode\\n          Logger.i(\\"shareCallback\\", `failed, code: ${errorCode}, msg: ${msg}`);\\n        }\\n      })\\n    }, photoAccessHelper.PhotoViewMIMETypes.IMAGE_TYPE);\\n  }\\n  // 发布单视频功能实现\\n  fn3 = () => {\\n    // 调用媒体选择方法，指定视频类型\\n    this.selectMedia<string>((url: string) => {\\n      // 创建单视频分享请求对象\\n      let shareRequest = createSingleVideoPublish(APPID);\\n      // 创建媒体URI列表\\n      let list: ArrayList<string> = new ArrayList();\\n      // 添加选中的视频URI\\n      list.add(url);\\n      // 设置媒体URI列表\\n      shareRequest.mediaUri = list;\\n      // 设置回调入口\\n      shareRequest.callbackLocalEntry = \\"EntryAbility\\";\\n      // 重要提示，这行代码不要复制\\n      shareRequest.harmonyAppId = harmonyAppID\\n      // 调用SDK分享接口\\n      kwaiOpenSdk.createApi().share(this.context, shareRequest, {\\n        // 分享成功回调\\n        onSuccess: (res) => {\\n          // 设置回调结果为成功\\n          this.callbackResult = true;\\n          Logger.i(\\"shareCallback\\", \\"success.......\\");\\n        },\\n        // 分享失败回调\\n        onError: (errorCode, msg) => {\\n          // 设置回调结果为失败\\n          this.callbackResult = false;\\n          // 保存错误信息\\n          this.errMsg = msg\\n          this.errCode = errorCode\\n          Logger.i(\\"shareCallback\\", `failed, code: ${errorCode}, msg: ${msg}`);\\n        }\\n      })\\n    }, photoAccessHelper.PhotoViewMIMETypes.VIDEO_TYPE);\\n  }\\n\\n  build() {\\n    Column({ space: 10 }) {\\n      Button(\\"授权\\")\\n        .onClick(this.fn1)\\n      Button(\\"发布单图\\")\\n        .onClick(this.fn2)\\n      Button(\\"发布单视频\\")\\n        .onClick(this.fn3)\\n    }\\n    .height(\'100%\')\\n    .width(\'100%\')\\n  }\\n\\n  // 媒体选择通用方法\\n  private selectMedia<T>(\\n    callback: (t: T) => void,\\n    type: photoAccessHelper.PhotoViewMIMETypes.IMAGE_TYPE | photoAccessHelper.PhotoViewMIMETypes.VIDEO_TYPE,\\n    num: number = 1\\n  ) {\\n    // 创建照片选择选项\\n    let photoOptions = new photoAccessHelper.PhotoSelectOptions();\\n    // 设置MIME类型（图片或视频）\\n    photoOptions.MIMEType = type;\\n    // 设置最大选择数量\\n    photoOptions.maxSelectNumber = num;\\n\\n    // 创建照片选择器\\n    let picker = new photoAccessHelper.PhotoViewPicker();\\n    // 调用选择方法\\n    picker.select(photoOptions).then((photoSelectResult: photoAccessHelper.PhotoSelectResult) => {\\n      // 获取选中的URI列表\\n      let uris: Array<string> = photoSelectResult.photoUris;\\n      if (uris.length > 0) {\\n        // 获取第一个URI\\n        let str = uris[0];\\n        // 提取文件名\\n        let fileName = str.substring(str.lastIndexOf(\'/\'));\\n        // 构建目标文件路径\\n        let desFilePath = this.context.getApplicationContext().tempDir + fileName;\\n        // 打开源文件（只读）\\n        let srcFile = fileIo.openSync(str, fileIo.OpenMode.READ_ONLY);\\n        // 打开目标文件（写，如不存在则创建）\\n        let desFile = fileIo.openSync(desFilePath, fileIo.OpenMode.WRITE_ONLY | fileIo.OpenMode.CREATE);\\n        // 复制文件内容\\n        fileIo.copyFileSync(srcFile.fd, desFile.fd)\\n        // 回调处理，传递文件URI\\n        callback?.(fileUri.getUriFromPath(desFilePath) as T);\\n      } else {\\n        // 未选择资源时显示提示\\n        this.getUIContext().getPromptAction().showToast({\\n          message: \'没有选择资源\'\\n        })\\n      }\\n    }).catch((error: BusinessError) => {\\n      // 选择出错时显示提示\\n      this.getUIContext().getPromptAction().showToast({\\n        message: \'选择资源error\'\\n      })\\n    })\\n  }\\n}\\n```\\n\\n## 参考文档\\n\\n1. **@kwai_open_platform/opensdk(V1.0.1)**\\n\\n   > https://open.kuaishou.com/platformDocs/develop/mobile-app/Harmony-OS.html#%E4%B8%80%E3%80%81%E8%AE%BE%E8%AE%A1%E7%9B%AE%E6%A0%87\\n\\n2. **快手接入鸿蒙应用指南**\\n\\n   > https://ohpm.openharmony.cn/#/cn/detail/@kwai_open_platform%2Fopensdk\\n\\n## 联系我\\n\\n可以加我微信，带你了解更多互联网 HarmonyOS相关的资讯。\\n\\n![](https://wsy996.obs.cn-east-3.myhuaweicloud.com:443/%E5%BE%AE%E4%BF%A1%E5%8F%B7%E5%92%8C%E4%BA%8C%E7%BB%B4%E7%A0%81.jpg)"}'),k={name:"鸿蒙开发技巧/HarmonyOS6 接入快手 SDK 指南/HarmonyOS6 接入快手 SDK 指南.md"};function r(E,s,d,g,y,c){return a(),n("div",null,[...s[0]||(s[0]=[l("",51)])])}const F=i(k,[["render",r]]);export{b as __pageData,F as default};
